// Wisdom of the Ancients / Мудрость Древних: «может потратить 1 Очко Бесчестия,
// чтобы попросить ГМа о подсказке к текущей ситуации». Очко — цена этой записи
// (runMechScriptEntry списывает её после кода и пишет карточку траты).
await ChatMessage.create({
  speaker: ChatMessage.getSpeaker({ actor }),
  content: `<div class="wh-ability-msg"><b>Мудрость Древних</b> — ${actor.name} просит ГМа о подсказке к текущей ситуации. ГМ отвечает максимально правдиво в пределах того, как персонаж понимает происходящее.</div>`
});
